package edu.uow.csit314.idp.config;

import edu.uow.csit314.idp.entity.IDPCategory;
import edu.uow.csit314.idp.repository.IDPCategoryRepository;
import java.util.List;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/** Small demo seed only; full-scale test data must be generated by the team. */
@Configuration
public class SampleDataInitializer {
    @Bean
    CommandLineRunner seedCategories(IDPCategoryRepository repository) {
        return args -> {
            if (repository.count() > 0) {
                return;
            }
            repository.saveAll(List.of(
                    new IDPCategory("Living Room", "Comfortable spaces for everyday life.", true),
                    new IDPCategory("Kitchen", "Practical layouts and thoughtful storage.", true),
                    new IDPCategory("Bedroom", "Restful private interiors.", true),
                    new IDPCategory("Bathroom", "Modern and functional wet spaces.", true),
                    new IDPCategory("Dining Room", "Spaces for meals and gatherings.", true),
                    new IDPCategory("Home Office", "Productive and flexible workspaces.", true),
                    new IDPCategory("Minimalist", "Clean lines and uncluttered design.", true),
                    new IDPCategory("Scandinavian", "Light materials and warm simplicity.", true),
                    new IDPCategory("Industrial", "Raw textures and urban materials.", true),
                    new IDPCategory("Contemporary", "Current, balanced interior aesthetics.", true),
                    new IDPCategory("Balcony", "Small outdoor living spaces.", true),
                    new IDPCategory("Commercial", "Offices, shops and public interiors.", true)
            ));
        };
    }
}
